import math

def quote(state):
    mid = (state['best_ask'] + state['best_bid']) // 2
    vol_imbalance = (state['bid_sizes'][0] - state['ask_sizes'][0]) / (state['bid_sizes'][0] + state['ask_sizes'][0])
    weighted_mid = (state['best_ask'] * state['bid_sizes'][0] + state['best_bid'] * state['ask_sizes'][0]) / (state['bid_sizes'][0] + state['ask_sizes'][0])

    bid = max(1, int(weighted_mid - 2))
    ask = min(state['best_ask'] + 1, int(weighted_mid + 2))

    bid_size = min(max(1, int(math.floor(5 * (1 - vol_imbalance)))), 5)
    ask_size = min(max(1, int(math.ceil(5 * vol_imbalance))), 5)

    if state['inventory'] > 0:
        bid = max(bid, state['best_bid'] - 1)
    elif state['inventory'] < 0:
        ask = min(ask, state['best_ask'] + 1)

    if bid >= ask:
        bid = max(1, ask - 1)

    return {"bid": bid, "bid_size": bid_size, "ask": ask, "ask_size": ask_size}
